            string stateName = "—";
            var launcher = GameLauncher.Instance;
            if (launcher != null && launcher.Fsm != null && launcher.Fsm.Current != null)
                stateName = launcher.Fsm.Current.Name;

            Txt_GameState.SetState(stateName);
        }

